#!/usr/bin/env node
// Turns one acceptance criterion into a Playwright test via Gemini.
// In the Agent Foreman product this step runs inside the Forge app (Forge LLM); this script
// simulates it locally. The generated file is reviewed and committed once ("human approved").
//
// Usage: GEMINI_API_KEY=... node foreman/generate-test.mjs "C3: <criterion text>" [--context public/page.html ...]
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { criterionHash, normalizeCriterionText } from "./criteria.mjs";

const args = process.argv.slice(2);
const criterionArg = args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--context");
const contextFiles = args.flatMap((a, i) => (args[i - 1] === "--context" ? [a] : []));
if (!criterionArg) {
  console.error('Usage: node foreman/generate-test.mjs "C3: criterion text" [--context file ...]');
  process.exit(2);
}

const m = criterionArg.match(/^\s*(C\d+)\s*:\s*([\s\S]+)$/);
if (!m) {
  console.error('Criterion must look like "C3: text"');
  process.exit(2);
}
const [, id, rawText] = m;
const text = normalizeCriterionText(rawText);
const hash = criterionHash(text);
const model = process.env.FOREMAN_MODEL || "gemini-flash-latest";
const FALLBACK_MODELS = ["gemini-flash-latest", "gemini-3.8-flash", "gemini-3.5-flash", "gemini-2.5-pro"];
const apiKey = process.env.GEMINI_API_KEY;
if (!apiKey) {
  console.error("GEMINI_API_KEY is not set");
  process.exit(2);
}

const context = (contextFiles.length ? contextFiles : ["public/forgot-password.html", "public/app.js"])
  .map((f) => `--- ${f} ---\n${readFileSync(f, "utf8")}`)
  .join("\n\n");

const prompt = `You write a single Playwright Test (TypeScript) that verifies ONE acceptance criterion of a web app.

Acceptance criterion ${id}: "${text}"

Rules:
- import { test, expect } from "@playwright/test";
- Exactly one test, titled "${id}: <short description>".
- The app is served at the configured baseURL; navigate with relative paths (e.g. page.goto("/forgot-password.html")).
- Use only elements that exist in the app source below. Prefer getByRole / getByLabel / getByText.
- Assert the criterion literally and strictly, including any time limit (use the expect timeout option set to the limit in ms). Do not loosen the criterion.
- Use a realistic test email such as "jane.doe@example.com".
- No network mocking, no page.waitForTimeout, no conditional logic that could skip the assertion.
- Output only the TypeScript code, no Markdown fences, no prose.

App source:
${context}`;

async function generate(modelName) {
  return fetch(`https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-goog-api-key": apiKey },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0 },
    }),
  });
}

// Free-tier models are frequently overloaded (503) or retired (404); try a few in order.
const candidates = [model, ...FALLBACK_MODELS.filter((x) => x !== model)];
let data;
let usedModel;
for (const candidate of candidates) {
  for (let attempt = 1; attempt <= 3 && !data; attempt++) {
    const res = await generate(candidate);
    if (res.ok) {
      data = await res.json();
      usedModel = candidate;
      break;
    }
    console.error(`Gemini ${candidate} attempt ${attempt}: HTTP ${res.status}`);
    if (res.status !== 503 && res.status !== 429) break;
    await new Promise((r) => setTimeout(r, 3000 * attempt));
  }
  if (data) break;
}
if (!data) {
  console.error("All Gemini models failed");
  process.exit(1);
}
let code = (data.candidates?.[0]?.content?.parts || []).map((p) => p.text || "").join("");
code = code.replace(/^\s*```[a-z]*\n/i, "").replace(/\n```\s*$/, "").trim();
if (!code.includes("@playwright/test") || !code.includes(`${id}:`)) {
  console.error("Model output does not look like a valid Foreman test:\n" + code);
  process.exit(1);
}

const header = [
  "// Generated by Agent Foreman. Do not edit: changes invalidate the approval for this criterion.",
  `// foreman-criterion-id: ${id}`,
  `// foreman-criterion-hash: ${hash}`,
  `// foreman-criterion-text: ${text}`,
  `// foreman-generated-by: ${usedModel}`,
  `// foreman-generated-at: ${new Date().toISOString()}`,
  "",
].join("\n");

const out = path.join("tests/foreman", `${id}.spec.ts`);
mkdirSync(path.dirname(out), { recursive: true });
writeFileSync(out, header + code + "\n");
console.log(`Wrote ${out}\ncriterion ${id} hash ${hash}`);
